import Ajax from"core/ajax";import Templates from"core/templates";import Notification from"core/notification";let init=e=>{let t=document.getElementById(e.rootid);t&&Ajax.call([{methodname:"block_personalprogress_get_dashboard",args:{courseid:e.courseid,blockinstanceid:e.blockinstanceid}}])[0].then(e=>Templates.render("block_personalprogress/dashboard",e)).then(e=>(t.innerHTML=e,t.setAttribute("aria-busy","false"),e)).catch(e=>{t.textContent=t.dataset.errorLabel||"",t.setAttribute("aria-busy","false"),Notification.exception(e)})};export{init};